<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_auth();
$code = strtoupper(trim((string)($_GET['code'] ?? '')));
if (!preg_match('/^[A-Z0-9]{4,32}$/', $code)) { http_response_code(404); exit('کلاس پیدا نشد.'); }
$pdo=db(); $q=$pdo->prepare('SELECT c.*,u.name AS teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id WHERE c.room_code=? LIMIT 1'); $q->execute([$code]); $class=$q->fetch();
if(!$class){http_response_code(404);exit('کلاس پیدا نشد.');}
$user = current_user();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($class['title'],ENT_QUOTES,'UTF-8')?> | کلاس زنده</title><style>html,body{margin:0;min-height:100%;background:#080d1b;color:#fff;font-family:Tahoma,Arial,sans-serif}#meeting{width:100%;min-height:100vh}.loading{min-height:100vh;display:grid;place-items:center;text-align:center;color:#b8c2d4}.box{width:min(760px,calc(100% - 32px));padding:30px;box-sizing:border-box}.diag{margin-top:18px;background:#10182b;border:1px solid #263451;border-radius:14px;padding:16px;text-align:right;line-height:1.8}.diag h3{margin:0 0 10px}.row{display:flex;gap:10px;padding:6px 0;border-bottom:1px solid #1d2940}.row:last-child{border-bottom:0}.k{color:#8fa0bd;min-width:170px}.v{color:#f2f5fa;word-break:break-word}.err{margin-top:15px;background:#3a1620;border:1px solid #713044;padding:14px;border-radius:12px;color:#ffd8e0;line-height:1.8;text-align:right}.ok{margin-top:15px;background:#10271e;border:1px solid #28563f;padding:14px;border-radius:12px;color:#d5ffe9;line-height:1.8;text-align:right}code{direction:ltr;unicode-bidi:embed}</style><script type="module">import{defineCustomElements}from'https://cdn.jsdelivr.net/npm/@cloudflare/realtimekit-ui@latest/loader/index.es2017.js';defineCustomElements();</script><script src="https://cdn.jsdelivr.net/npm/@cloudflare/realtimekit@latest/dist/browser.js"></script></head><body><div id="meeting"><div class="loading"><div class="box"><h2>در حال اتصال به کلاس 🎥</h2><p>در حال آماده‌سازی دوربین و میکروفون...</p><div class="diag"><h3>اطلاعات اتصال (بدون اطلاعات محرمانه)</h3><div class="row"><span class="k">Class ID</span><span class="v"><?= (int)$class['id'] ?></span></div><div class="row"><span class="k">عنوان کلاس</span><span class="v"><?=htmlspecialchars((string)$class['title'],ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">Room Code</span><span class="v"><code><?=htmlspecialchars($code,ENT_QUOTES,'UTF-8')?></code></span></div><div class="row"><span class="k">Teacher</span><span class="v"><?=htmlspecialchars((string)$class['teacher_name'],ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">User ID</span><span class="v"><?=htmlspecialchars((string)($user['id'] ?? ''),ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">User Name</span><span class="v"><?=htmlspecialchars((string)($user['name'] ?? ''),ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">User Role</span><span class="v"><?=htmlspecialchars((string)($user['role'] ?? ''),ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">Class Status</span><span class="v"><?=htmlspecialchars((string)$class['status'],ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">Starts At</span><span class="v"><?=htmlspecialchars((string)($class['starts_at'] ?? 'NULL'),ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">Expires At</span><span class="v"><?=htmlspecialchars((string)($class['expires_at'] ?? 'NULL'),ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">Guest Access</span><span class="v"><?=!empty($class['allow_guest'])?'Enabled':'Disabled'?></span></div><div class="row"><span class="k">Realtime Meeting ID</span><span class="v" id="meeting-id"><?=htmlspecialchars((string)($class['realtime_meeting_id'] ?? 'Not created'),ENT_QUOTES,'UTF-8')?></span></div><div class="row"><span class="k">API Token</span><span class="v">🔒 Hidden</span></div></div><div id="error"></div></div></div></div><script>(async()=>{const error=document.getElementById('error');try{const r=await fetch('/realtime/token.php?class_id=<?= (int)$class['id'] ?>',{credentials:'same-origin'});const d=await r.json();if(d.meeting_id)document.getElementById('meeting-id').textContent=d.meeting_id;if(!r.ok||!d.ok){const details=d.diagnostics||{};let html='<div class="err"><b>خطا:</b> '+String(d.error||'خطا در دریافت دسترسی')+'<div class="diag"><h3>تشخیص فنی امن</h3>';for(const [k,v] of Object.entries(details)){html+='<div class="row"><span class="k">'+k+'</span><span class="v">'+String(v??'')+'</span></div>';}html+='</div></div>';error.innerHTML=html;return;}error.innerHTML='<div class="ok">احراز هویت و صدور دسترسی RealtimeKit با موفقیت انجام شد.</div>';const meeting=await RealtimeKitClient.init({authToken:d.token,defaults:{audio:true,video:true}});const el=document.getElementById('meeting');el.innerHTML='<rtk-meeting id="rtk" show-setup-screen="true"></rtk-meeting>';document.getElementById('rtk').meeting=meeting;await meeting.join();}catch(e){error.innerHTML='<div class="err">'+String(e.message||e)+'</div>'}})();</script></body></html>
